query GetUserBetaLinks($userId: String!, $limit: Int, $offset: Int) {
  userBetaLinks(userId: $userId, limit: $limit, offset: $offset) {
    climbName
    boardType
    layoutId
    betaLink {
      climbUuid
      link
      foreignUsername
      angle
      thumbnail
      isListed
      createdAt
      tickUuid
      boardId
    }
  }
}
